solution.solution.cpp:
#include <atomic>
#include <cstdint>
#include <new>
#include <optional>

struct alignas(64) RingHeader
{
    std::atomic<std::uint32_t> head;
    char pad1[60];
    std::atomic<std::uint32_t> tail;
    char pad2[60];
    std::uint32_t capacity;
    std::atomic<std::uint32_t> dropped;
};

class Ring
{
public:
    Ring(void* memory, std::uint32_t capacity, bool create)
        : header{ create ? new (memory) RingHeader{} : static_cast<RingHeader*>(memory) },
          slots{ reinterpret_cast<std::uint32_t*>(static_cast<std::byte*>(memory) + sizeof(RingHeader)) }
    {
        if (create)
        {
            header->head.store(0, std::memory_order_relaxed);
            header->tail.store(0, std::memory_order_relaxed);
            header->capacity = capacity;
            header->dropped.store(0, std::memory_order_relaxed);
        }
    }

    bool push(std::uint32_t value)
    {
        const std::uint32_t head{ header->head.load(std::memory_order_relaxed) };
        const std::uint32_t tail{ header->tail.load(std::memory_order_acquire) };
        if (head - tail == header->capacity) return false;
        slots[head & (header->capacity - 1)] = value;
        header->head.store(head + 1, std::memory_order_release);
        return true;
    }

    void pushOrDrop(std::uint32_t value)
    {
        if (!push(value)) header->dropped.fetch_add(1, std::memory_order_relaxed);
    }

    std::optional<std::uint32_t> pop()
    {
        const std::uint32_t tail{ header->tail.load(std::memory_order_relaxed) };
        const std::uint32_t head{ header->head.load(std::memory_order_acquire) };
        if (head == tail) return std::nullopt;
        const std::uint32_t value{ slots[tail & (header->capacity - 1)] };
        header->tail.store(tail + 1, std::memory_order_release);
        return value;
    }

    std::uint32_t size() const
    {
        return header->head.load(std::memory_order_acquire) - header->tail.load(std::memory_order_acquire);
    }

    std::uint32_t dropped() const { return header->dropped.load(std::memory_order_relaxed); }

private:
    RingHeader* header;
    std::uint32_t* slots;
};

unitTests:
#include <thread>
#include <vector>
struct alignas(64) Block { unsigned char bytes[sizeof(RingHeader) + 4 * 1024]; };

TEST("first in, first out") {
    static Block block{};
    Ring producer{ block.bytes, 8, true };
    Ring consumer{ block.bytes, 8, false };
    CHECK(!consumer.pop().has_value());
    for (std::uint32_t v{ 1 }; v <= 5; ++v) CHECK(producer.push(v));
    CHECK_EQ(consumer.size(), 5u);
    CHECK_EQ(consumer.pop().value_or(0), 1u);
    CHECK_EQ(consumer.pop().value_or(0), 2u);
    CHECK_EQ(producer.size(), 3u);
}
TEST("full rings and wrapping") {
    static Block block{};
    Ring p{ block.bytes, 4, true };
    Ring c{ block.bytes, 4, false };
    for (std::uint32_t round{ 0 }; round < 10; ++round)
    {
        for (std::uint32_t k{ 0 }; k < 4; ++k) CHECK(p.push(round * 10 + k));
        CHECK(!p.push(999));
        for (std::uint32_t k{ 0 }; k < 4; ++k) CHECK_EQ(c.pop().value_or(12345), round * 10 + k);
        CHECK(!c.pop().has_value());
    }
}
TEST("dropping when full") {
    static Block block{};
    Ring p{ block.bytes, 2, true };
    p.pushOrDrop(1); p.pushOrDrop(2); p.pushOrDrop(3); p.pushOrDrop(4);
    CHECK_EQ(p.dropped(), 2u);
    Ring c{ block.bytes, 2, false };
    CHECK_EQ(c.dropped(), 2u);
    CHECK_EQ(c.pop().value_or(0), 1u);
}
TEST("a real producer and consumer") {
    static Block block{};
    Ring p{ block.bytes, 64, true };
    Ring c{ block.bytes, 64, false };
    constexpr std::uint32_t N{ 200000 };
    std::thread producer{ [&] { for (std::uint32_t v{ 0 }; v < N; ++v) while (!p.push(v)) std::this_thread::yield(); } };
    std::uint32_t expected{ 0 };
    bool inOrder{ true };
    while (expected < N)
    {
        if (const auto v{ c.pop() }) { if (*v != expected) inOrder = false; ++expected; }
        else std::this_thread::yield();
    }
    producer.join();
    CHECK(inOrder);
    CHECK_EQ(c.size(), 0u);
}

